# alien-swarm's audio: carts/src/alien-swarm/audio.json.
#   python3 carts/src/alien-swarm/audio.py carts/src/alien-swarm/audio.json
# Written by tools/devkit/music/script.py from the audio.json, so the music can be edited as text: instruments
# I00 to I1F are the slots, patterns and effects are tracker text (a row a line; a cell is "NNN II V FFF": note,
# instrument, volume, effect, as in the console's tracker), songs are order lists. Song toolkit: tools/devkit/music/kit.py.
# Five songs (0 the title, 1 to 4 the planets: Luna Outpost, Frost Moon, Jungle World, The Hive) and the effects in the
# numbers of SFX in code.js. The new sound chip (SPEC 5): sampled instruments (a choir for the pad: space), an echo for
# each song, the leads (channel 0) an octave lower than they were written (up high a lead pierces); the songs use
# channels 0 to 5 and the effects take turns on 7 and 6; the lasers and blips stay chip sounds. After a change:
# node tools/devkit/music/loud.mjs carts/alien-swarm.nova --check.
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '../../../tools/devkit/music'))
from kit import *

a = Audio(chip=2)

# --- Samples ---
a.samples.append({'rate': 16000, 'loop': None, 'data': ''})  # 0
a.samples.append({'rate': 16000, 'loop': None, 'data': ''})  # 1

# --- Instruments ---
a.voice('I00', 'brass', 6, -0.15)                       # the lead
a.voice('I01', 'bass', 12)                              # the bass
a.instrument('I02', 'noise-short', 0, 2, 0, 0, 5, (0, 0), 0.25, echo=2)   # the hats
a.instrument('I03', 'noise-short', 0, 7, 2, 4, 4, (0, 0), 0.25, echo=3)
a.instrument('I04', 'noise', 0, 6, 0, 0, 8, (0, 0), None)
a.voice('I05', 'choir', 5, 0.2)                         # the pad: a choir
a.instrument('I06', 'pulse12', 0, 3, 0, 0, 9, (0, 0), None, echo=4)    # effects: blips
a.voice('I07', 'celesta', 12)                           # effects: chimes
a.voice('I08', 'tom', 12)                               # effects: a refusal thud
a.voice('I09', 'marimba', 9, -0.1)                      # a staccato lead
a.voice('I0A', 'pluck', 12, 0.25, d=24)                 # the arpeggio
a.voice('I0B', 'flute', 3, -0.2, a=3)                   # a soft lead (the title's first)
a.voice('I0C', 'brass', 6)                              # a horn lead
a.voice('I0D', 'brass', 10, -0.1, d=6, s=11, r=6)       # effects: the victory fanfare
a.instrument('I0E', 'sample', 0, 0, 15, 0, 15, (0, 0), None, sample=0, echo=2)   # kick
a.instrument('I0F', 'sample', 0, 0, 15, 0, 12, (0, 0), None, sample=1, echo=5)   # snare
a.instrument('I10', 'saw', 1, 10, 6, 8, 5, (1, 5), 0.3)
a.voice('I11', 'brass', 9, -0.15, a=6)                  # effects: the base lost
a.voice('I12', 'epiano', 8, 0.3, d=12)                  # short chords
a.voice('I13', 'brass', 5)                              # the steady lead
a.instrument('I14', 'pulse12', 0, 0, 15, 2, 7, (0, 0), None)   # the boss's warning
a.voice('I15', 'epiano', 8, 0.25, d=10, s=0)            # off-beat chords
a.instrument('I16', 'pulse12', 0, 3, 0, 0, 6, (0, 0), None)
a.instrument('I17', 'noise', 0, 7, 0, 0, 10, (0, 0), None)
a.instrument('I18', 'noise-short', 0, 4, 0, 0, 7, (0, 0), None)
a.instrument('I19', 'pulse25', 0, 8, 4, 4, 11, (2, 10), None)
a.instrument('I1A', 'saw', 0, 4, 2, 2, 5, (3, 20), None)
a.instrument('I1B', 'noise-short', 0, 10, 0, 0, 5, (0, 0), None)
a.voice('I1C', 'flute', 4, -0.1)                        # the solo lead
a.voice('I1D', 'brass', 5, -0.15, a=6)                  # a soft horn lead

